cd out && bun scratch.ts | python3 -c "
import sys,json,re
txt=sys.stdin.read()
for blk in re.split(r'\n(?=\d{4}-\d\d-\d\d )', txt):
  d,j=blk.split(' ',1); r=json.loads(j); print('==',d)
  for k,v in r.items():
    for row in v:
      row.pop('evidence',None); print(k, json.dumps(row))
"

